/* Ritme service worker.
 *
 * Generated by scripts/generate-version.mjs — do not edit public/sw.js
 * directly; edit scripts/sw.template.js instead. __APP_VERSION__ is stamped
 * per release so the browser sees a byte-different worker and fires
 * `updatefound`, which drives the in-app update button.
 *
 * Caching policy:
 *  - App shell essentials are precached (offline page, icons, manifest).
 *  - Navigations: network-first, offline.html fallback.
 *  - Static assets (/_next/static, fonts, images): stale-while-revalidate.
 *  - NEVER cached: /api/* (health data — privacy, CLAUDE.md §11), version.json
 *    (update source of truth), sw.js itself.
 */

const APP_VERSION = '__APP_VERSION__';
const PRECACHE = `ritme-precache-v${APP_VERSION}`;
const RUNTIME = `ritme-runtime-v${APP_VERSION}`;

const PRECACHE_URLS = [
  '/offline.html',
  '/manifest.webmanifest',
  '/logo.webp',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/maskable-192.png',
  '/icons/maskable-512.png',
  '/icons/apple-touch-icon.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(PRECACHE).then((cache) => cache.addAll(PRECACHE_URLS)),
  );
  // Do NOT skipWaiting here — activation is user-driven via the update button.
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key !== PRECACHE && key !== RUNTIME)
          .map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
  if (event.data?.type === 'CLEAR_RUNTIME_CACHE') {
    event.waitUntil(caches.delete(RUNTIME));
  }
});

function isStaticAsset(url) {
  return (
    url.pathname.startsWith('/_next/static/') ||
    url.pathname.startsWith('/icons/') ||
    url.pathname.startsWith('/fonts/') ||
    /\.(?:png|webp|jpg|jpeg|svg|gif|ico|woff2?)$/.test(url.pathname)
  );
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Bypass entirely: API (health data must never rest in Cache Storage),
  // the version manifest, and the worker itself.
  if (
    url.pathname.startsWith('/api/') ||
    url.pathname === '/version.json' ||
    url.pathname === '/sw.js'
  ) {
    return;
  }

  // Navigations: network-first with offline fallback.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(async () => {
        const cached = await caches.match('/offline.html');
        return cached ?? Response.error();
      }),
    );
    return;
  }

  // Static assets: stale-while-revalidate.
  if (isStaticAsset(url)) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(RUNTIME);
        const cached = await cache.match(request);
        const network = fetch(request)
          .then((response) => {
            if (response.ok) {
              cache.put(request, response.clone());
            }
            return response;
          })
          .catch(() => undefined);
        return cached ?? (await network) ?? Response.error();
      })(),
    );
  }
});
